/* CSA5111 Question 28: independent executable */
#include "common/crypto_common.h"
static void q28(void){uint64_t p=(uint64_t)readint("Public prime modulus p (small demo): "),g=(uint64_t)readint("Public generator g: "),a=(uint64_t)readint("Alice secret a: "),b=(uint64_t)readint("Bob secret b: ");if(p<3||!a||!b){puts("Use p>=3 and positive private exponents.");return;}uint64_t A=modpow64(g,a,p),B=modpow64(g,b,p),ka=modpow64(B,a,p),kb=modpow64(A,b,p);printf("Alice sends g^a mod p = %llu\nBob sends g^b mod p = %llu\n",(unsigned long long)A,(unsigned long long)B);printf("Alice shared key = %llu; Bob shared key = %llu\n",(unsigned long long)ka,(unsigned long long)kb);if(ka==kb)puts("Keys match.");else puts("Keys do not match: check group parameters.");int found=-1;for(uint64_t x=1;x<p;x++)if(modpow64(g,x,p)==A){found=(int)x;break;}printf("Toy Eve discrete-log search: %s\n",found<0?"not found in search":"can recover Alice exponent in this small group");puts("If both parties instead send x^a with their private x as the base and public a as exponent, the usual DH symmetry is lost: (x_B^a)^x_A need not equal (x_A^a)^x_B. Standard DH uses the common public base g raised to each private exponent.");puts("Real exchanges require large safe groups and authentication to prevent MITM.");}
int main(void){ OSSL_PROVIDER_load(NULL,"default"); OSSL_PROVIDER_load(NULL,"legacy"); q28(); return 0; }
